{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, the closest glycosylated polyketide antitumor antibiotic analogue, showed poor CNS penetration with a CSF:plasma ratio of only 0.12 in monkeys, supporting that large glycosylated antitumor agents such as doxorubicin have limited meaningful brain access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Digitoxin, a bulky cardiac glycoside, exhibited a very low CSF:plasma ratio (0.01-0.03) in dogs, indicating that glycoside natural products with multiple polar sugars are generally poor BBB penetrants; doxorubicin shares this glycoside architecture.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "DX-52-1 showed a brain-to-blood ratio of about 0.02 in mice, demonstrating that compounds with ionizable/basic groups and large polar surfaces are strongly efflux-limited at the BBB, a liability relevant to doxorubicin's amino sugar.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Emodin-8-O-β-D-glucoside was detected in rat brain, but this occurred under ischemia-reperfusion conditions with BBB disruption, so it does not establish meaningful CNS access under normal systemic administration and is outweighed by the poor-penetration glycoside evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Doxorubicin is a P-gp substrate anthracycline glycoside with known poor BBB penetration. Cyclosporine co-treatment may partially inhibit efflux, but the closest glycoside antitumor and cardiac glycoside evidence indicates that CNS exposure remains inadequate for meaningful access.",
  "evidence_gaps": [
    "No direct retrieved evidence for doxorubicin plus cyclosporine co-treatment; the magnitude of P-gp inhibition on doxorubicin brain uptake is uncertain.",
    "Most permeable glycoside evidence comes from smaller aglycones or disrupted-BBB conditions, limiting transferability to doxorubicin."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

